{
  "findings": [
    {
      "check_id": "CKV_AWS_52",
      "title": "Listener is not using HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "HIGH",
      "explanation": "The listener is configured to use HTTP on port 80, which does not encrypt traffic. This exposes sensitive data to potential interception. HTTPS should be used to secure communication."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-2016-08\"\n  certificate_arn   = \"arn:aws:acm:region:account-id:certificate/certificate-id\"\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Updated the listener to use HTTPS on port 443, added an SSL policy, and included a placeholder for the certificate ARN to secure traffic."
}
